using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;

namespace MultiTenantCLI.Server
{
    public class TenantContext
    {
        public string TenantId { get; set; }
        public string SessionToken { get; set; }
        public DateTime IssuedAt { get; set; }
    }

    public class AntiCsrfMiddleware
    {
        private readonly RequestDelegate _next;
        private static readonly HashSet<string> SafeMethods = new(StringComparer.OrdinalIgnoreCase)
            { "GET", "HEAD", "OPTIONS" };

        public AntiCsrfMiddleware(RequestDelegate next)
        {
            _next = next;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (SafeMethods.Contains(context.Request.Method))
            {
                await _next(context);
                return;
            }

            var tenantCtx = context.Items["TenantContext"] as TenantContext;
            if (tenantCtx == null)
            {
                context.Response.StatusCode = 401;
                return;
            }

            var originHeader = context.Request.Headers["Origin"].FirstOrDefault();
            var refererHeader = context.Request.Headers["Referer"].FirstOrDefault();
            var csrfToken = context.Request.Headers["X-CSRF-Token"].FirstOrDefault();
            var cookieToken = context.Request.Cookies["csrf_binding"];

            if (!ValidateCsrfBinding(csrfToken, cookieToken, tenantCtx, context.Request))
            {
                context.Response.StatusCode = 403;
                await context.Response.WriteAsync("CSRF validation failed");
                return;
            }

            await _next(context);
        }

        private bool ValidateCsrfBinding(string headerToken, string cookieToken,
            TenantContext tenant, HttpRequest request)
        {
            if (string.IsNullOrEmpty(headerToken) || string.IsNullOrEmpty(cookieToken))
                return false;

            // Validate token structure: base64(tenantId:timestamp:hmac)
            try
            {
                var headerBytes = Convert.FromBase64String(headerToken);
                var headerParts = Encoding.UTF8.GetString(headerBytes).Split(':');
                if (headerParts.Length != 3) return false;

                var cookieBytes = Convert.FromBase64String(cookieToken);
                var cookieParts = Encoding.UTF8.GetString(cookieBytes).Split(':');
                if (cookieParts.Length != 3) return false;

                // Verify tenant isolation - token must belong to current tenant
                if (headerParts[0] != tenant.TenantId) return false;

                // Verify double-submit: header token tenant must match cookie token tenant
                if (headerParts[0] != cookieParts[0]) return false;

                // Verify HMAC integrity of BOTH tokens
                var expectedHeaderHmac = ComputeTokenHmac(headerParts[0], headerParts[1], tenant.SessionToken);
                if (!CryptographicEquals(headerParts[2], expectedHeaderHmac)) return false;

                var expectedCookieHmac = ComputeTokenHmac(cookieParts[0], cookieParts[1], tenant.SessionToken);
                if (!CryptographicEquals(cookieParts[2], expectedCookieHmac)) return false;

                // Verify timestamp freshness (tokens valid for 4 hours)
                if (long.TryParse(headerParts[1], out var headerTimestamp))
                {
                    var issued = DateTimeOffset.FromUnixTimeSeconds(headerTimestamp);
                    if (DateTimeOffset.UtcNow - issued > TimeSpan.FromHours(4))
                        return false;
                }
                else return false;

                if (long.TryParse(cookieParts[1], out var cookieTimestamp))
                {
                    var issued = DateTimeOffset.FromUnixTimeSeconds(cookieTimestamp);
                    if (DateTimeOffset.UtcNow - issued > TimeSpan.FromHours(4))
                        return false;
                }
                else return false;

                return true;
            }
            catch
            {
                return false;
            }
        }

        private static string ComputeTokenHmac(string tenantId, string timestamp, string sessionKey)
        {
            using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(sessionKey));
            var payload = Encoding.UTF8.GetBytes($"{tenantId}:{timestamp}");
            return Convert.ToBase64String(hmac.ComputeHash(payload));
        }

        private static bool CryptographicEquals(string a, string b)
        {
            if (a == null || b == null) return false;
            var aBytes = Encoding.UTF8.GetBytes(a);
            var bBytes = Encoding.UTF8.GetBytes(b);
            return CryptographicOperations.FixedTimeEquals(aBytes, bBytes);
        }
    }

    public class TenantResolutionMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ITenantStore _tenantStore;

        public TenantResolutionMiddleware(RequestDelegate next, ITenantStore tenantStore)
        {
            _next = next;
            _tenantStore = tenantStore;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var tenantHeader = context.Request.Headers["X-Tenant-Id"].FirstOrDefault();
            var authCookie = context.Request.Cookies["session"];

            if (!string.IsNullOrEmpty(authCookie))
            {
                var session = await _tenantStore.ResolveSession(authCookie);
                if (session != null)
                {
                    context.Items["TenantContext"] = session;
                }
            }

            await _next(context);
        }
    }

    public interface ITenantStore
    {
        Task<TenantContext> ResolveSession(string sessionCookie);
    }

    [ApiController]
    [Route("api/tenant/{tenantId}/commands")]
    public class CommandController : ControllerBase
    {
        [HttpPost("execute")]
        public IActionResult ExecuteCommand([FromRoute] string tenantId, [FromBody] CommandRequest request)
        {
            var ctx = HttpContext.Items["TenantContext"] as TenantContext;
            if (ctx == null || ctx.TenantId != tenantId)
                return Forbid();

            // Execute CLI command in tenant sandbox
            return Ok(new { status = "executed", command = request.Command, tenant = tenantId });
        }
    }

    public class CommandRequest
    {
        public string Command { get; set; }
        public Dictionary<string, string> Parameters { get; set; }
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
            services.AddSingleton<ITenantStore, InMemoryTenantStore>();
        }

        public void Configure(IApplicationBuilder app)
        {
            app.UseMiddleware<TenantResolutionMiddleware>();
            app.UseMiddleware<AntiCsrfMiddleware>();
            app.UseRouting();
            app.UseEndpoints(e => e.MapControllers());
        }
    }

    public class InMemoryTenantStore : ITenantStore
    {
        private static readonly Dictionary<string, TenantContext> Sessions = new();

        public Task<TenantContext> ResolveSession(string sessionCookie)
        {
            Sessions.TryGetValue(sessionCookie, out var ctx);
            return Task.FromResult(ctx);
        }
    }
}
